// Rotate an array `a` to the left by `offset` positions.
// For each i in [0, n): b[i] = a[(i + offset) % n].
// Empty input produces empty output.
pub fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    // Normalize offset so we never do unnecessary work.
    let k = offset % n;

    // Allocate output with the same length and fill by index mapping.
    let mut b = vec![0i32; n];
    for i in 0..n {
        b[i] = a[(i + k) % n];
    }
    b
}

